import java.util.Properties

plugins {
    alias(libs.plugins.android.application)
}

kotlin {
    jvmToolchain(17)

    compilerOptions {
        freeCompilerArgs.add("-Xannotation-default-target=param-property")
    }
}

// AGP doesn't expose `local.properties` as Gradle project properties in
// 9.x, so we load it explicitly with the standard `java.util.Properties`
// API. `local.properties` is auto-generated by Android Studio (with
// `sdk.dir`) and is gitignored, so it's the conventional home for
// credentials that must never enter version control.
val keystorePropertiesFile = rootProject.file("local.properties")
val keystoreProperties = Properties().apply {
    if (keystorePropertiesFile.exists()) {
        keystorePropertiesFile.inputStream().use { load(it) }
    }
}
val keystorePath = keystoreProperties.getProperty("storeFile")?.let(::file)

/*
 * When this build was made, in epoch milliseconds, used by the nightly update
 * check to tell one nightly from the next (they share a version code). The
 * deploy passes an explicit `-PvestiBuildTime=…` so the APK and the manifest it
 * publishes agree; other builds leave it at 0, which never looks newer than a
 * published nightly.
 */
val buildTime: Long = (findProperty("vestiBuildTime") as String?)?.toLongOrNull() ?: 0L

android {
    namespace = "org.vestifeed"

    compileSdk {
        version = release(37) { minorApiLevel = 1 }
    }

    defaultConfig {
        applicationId = "org.vestifeed"
        minSdk = 33
        targetSdk = 37
        versionCode = 24
        versionName = "0.4.3"

        buildConfigField("long", "BUILD_TIME", "${buildTime}L")

        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    signingConfigs {
        create("release") {
            storeFile = keystorePath
            storePassword = keystoreProperties.getProperty("storePassword")
            keyAlias = keystoreProperties.getProperty("keyAlias")
            keyPassword = keystoreProperties.getProperty("keyPassword")
                ?: keystoreProperties.getProperty("storePassword")
        }
    }

    buildTypes {
        debug {
            applicationIdSuffix = ".debug"
        }

        release {
            signingConfig = signingConfigs.getByName("release")

            isMinifyEnabled = true
            isShrinkResources = true

            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt")
            )
        }

        create("nightly") {
            initWith(getByName("release"))
            applicationIdSuffix = ".nightly"
        }
    }

    buildFeatures {
        buildConfig = true
    }

    testOptions {
        unitTests {
            isReturnDefaultValues = true
        }
    }

    lint {
        disable += "GradleDependency"
    }
}

dependencies {
    implementation(project(":shared"))
    implementation(project(":ui"))

    // Coroutines
    implementation(libs.kotlinx.coroutines)

    // AndroidX
    // The bundled driver, not the platform one: the schema uses STRICT tables
    // (SQLite 3.37+), which Android 13's system SQLite predates. Bundling keeps
    // the same SQLite on every host the app runs on.
    implementation(libs.androidx.sqlite.bundled)
    implementation(libs.androidx.activity)
    implementation(libs.androidx.activity.compose)

    // Material Components themes the host; Compose Material3 draws the UI.
    implementation(libs.material)
    implementation(libs.androidx.lifecycle.runtime)
    implementation(libs.androidx.lifecycle.viewmodel.compose)
    implementation(libs.androidx.work)
    implementation(libs.androidx.browser)
    androidTestImplementation(libs.androidx.work.testing)

    // Unit tests
    testImplementation(libs.junit)

    // Instrumented tests
    androidTestImplementation(libs.junit)
    androidTestImplementation(libs.androidx.test.core)
    androidTestImplementation(libs.androidx.test.rules)
    androidTestImplementation(libs.androidx.test.espresso.core)
    androidTestImplementation(libs.androidx.test.runner)
    androidTestImplementation(libs.androidx.test.ext.junit)
    androidTestImplementation(libs.androidx.compose.ui.test.junit4)
    debugImplementation(libs.androidx.compose.ui.test.manifest)
}

/**
 * Writes the update manifest the nightly's update check reads. `devtools
 * publish` uploads it next to the APK on the server.
 * Kept in Gradle so the version code, name and build time in the manifest are
 * exactly the ones baked into the APK.
 */
val writeUpdateManifest by tasks.registering {
    val outputFile = layout.buildDirectory.file("updates/vesti-nightly.json")
    outputs.file(outputFile)
    val versionCode = android.defaultConfig.versionCode ?: 1
    val versionName = android.defaultConfig.versionName ?: ""
    val buildTimeValue = buildTime
    // Declared as inputs so a new build time (a fresh rollout) re-runs the task
    // instead of leaving the previous manifest in place.
    inputs.property("versionCode", versionCode)
    inputs.property("versionName", versionName)
    inputs.property("buildTime", buildTimeValue)
    doLast {
        val file = outputFile.get().asFile
        file.parentFile.mkdirs()
        file.writeText(
            "{\"versionCode\":$versionCode,\"versionName\":\"$versionName\"," +
                "\"buildTime\":$buildTimeValue," +
                "\"apk\":\"https://vestifeed.org/releases/vesti-nightly.apk\"}"
        )
    }
}
